# imgdiff.gd -- <a.png> <b.png>: farklı piksellerin satır bantları (özgün piksel).
func _init() -> void:
	var args := OS.get_cmdline_user_args()
	var a := Image.load_from_file(args[0])
	var b := Image.load_from_file(args[1])
	if a.get_size() != b.get_size():
		print("DIFF|size|", a.get_size(), b.get_size())
		quit()
		return
	var w := a.get_width()
	var h := a.get_height()
	var bands: Array = []
	var total := 0
	var cur := Vector4i(-1, -1, 0, 0)  # y0,y1,xmin,xmax
	for y in h:
		var n := 0
		var xmin := w
		var xmax := -1
		for x in w:
			var pa := a.get_pixel(x, y)
			var pb := b.get_pixel(x, y)
			if absf(pa.r - pb.r) + absf(pa.g - pb.g) + absf(pa.b - pb.b) > 0.02:
				n += 1
				xmin = mini(xmin, x)
				xmax = maxi(xmax, x)
		total += n
		if n > 0:
			if cur.x >= 0 and y - cur.y <= 2:
				cur = Vector4i(cur.x, y, mini(cur.z, xmin), maxi(cur.w, xmax))
			else:
				if cur.x >= 0:
					bands.append(cur)
				cur = Vector4i(y, y, xmin, xmax)
	if cur.x >= 0:
		bands.append(cur)
	print("DIFF|total=%d|bands=%d" % [total, bands.size()])
	for bd in bands:
		print("  y %d-%d x %d-%d" % [bd.x, bd.y, bd.z, bd.w])
	quit()
